namespace KAONOMI.ImmuneSystem;

using System.Collections.Concurrent;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
using KAONOMI.ImmuneSystem.History;
using KAONOMI.ImmuneSystem.Images;
using KAONOMI.ImmuneSystem.Office;
using KAONOMI.ImmuneSystem.Scanning;

/// <summary>
/// KAONOMI.ImmuneSystem: walks the folders of the machine, finds the images generated by AI (from what they declare in
/// their metadata) and the code in Office files (VBA and XLM macros, DDE, OLE objects, Power Query, code written as
/// text…), and writes everything in a JSON report. The progress goes to the error output, so the report can be written on
/// the standard output (<c>--out -</c>).
/// </summary>
internal static class Program
{
    private static int Main(string[] args)
    {
        Options options;
        try
        {
            options = Options.Parse(args);
        }
        catch (ArgumentException ex)
        {
            Console.Error.WriteLine(ex.Message);
            Console.Error.WriteLine("KAONOMI.ImmuneSystem --help for the options");
            return 2;
        }
        if (options.Help)
        {
            Console.WriteLine(Options.Usage);
            return 0;
        }

        var roots = options.Roots.Count > 0 ? options.Roots.Select(Path.GetFullPath).ToList() : FileWalker.DefaultRoots(options.Machine).ToList();
        foreach (var root in roots.Where(r => !Directory.Exists(r)))
        {
            Console.Error.WriteLine($"{root} is not a folder");
            return 2;
        }

        using var cancel = new CancellationTokenSource();
        Console.CancelKeyPress += (_, e) =>
        {
            e.Cancel = true;
            cancel.Cancel();
        };

        // A program that runs the scan (--progress) stops it by writing "cancel" on its standard input: a signal can be
        // lost (ignored by a parent, or Windows), the report is written all the same.
        if (options.Progress && Console.IsInputRedirected)
            new Thread(() =>
            {
                try
                {
                    while (Console.In.ReadLine() is { } line)
                        if (line.Trim().Equals("cancel", StringComparison.OrdinalIgnoreCase))
                        {
                            cancel.Cancel();
                            return;
                        }
                }
                catch (IOException)
                {
                    // The input is closed: the scan goes on.
                }
            }) { IsBackground = true, Name = "cancel" }.Start();

        var started = DateTime.Now;
        var clock = Stopwatch.StartNew();
        var stats = new ScanStats();
        var walker = new FileWalker(options, stats);
        var office = new OfficeInspector(options);
        var images = new ConcurrentBag<AiImage>();
        var officeFiles = new ConcurrentBag<OfficeFile>();
        var errors = new ConcurrentQueue<ScanError>();
        var maxOffice = (long)options.MaxSizeMb << 20;
        long files = 0, imagesSeen = 0, officeSeen = 0, tooLarge = 0, errorCount = 0;

        Log(options, $"KAONOMI.ImmuneSystem: {(options.Images ? "AI images" : "")}{(options.Images && options.Office ? " and " : "")}{(options.Office ? "code in Office files" : "")} in {string.Join(", ", roots)}");

        void Tick() => Progress(options, Interlocked.Read(ref files), stats.Directories, Interlocked.Read(ref imagesSeen), Interlocked.Read(ref officeSeen),
            images.Count, officeFiles.Count, walker.Current, clock.Elapsed.TotalSeconds);
        using var progress = options.Progress || !options.Quiet && !Console.IsErrorRedirected ? new Timer(_ => Tick(), null, 250, options.Progress ? 250 : 500) : null;

        // The browser histories first: a few databases, read in a second or two.
        BrowserReport? browsers = null;
        if (options.History)
        {
            walker.Current = "Browser histories";
            Log(options, "Reading the browser histories");
            browsers = HistoryScanner.Scan(options.HistoryHome ?? Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
                s => Found(options, $"AI service [{s.Category}] {s.Name}: {s.Visits:N0} visits", "history", s.Name, $"{s.Name} · {s.Visits:N0} visits", s.Category),
                cancel.Token);
        }

        try
        {
            Parallel.ForEach(
                walker.Files(roots, cancel.Token),
                new ParallelOptions { MaxDegreeOfParallelism = options.Threads, CancellationToken = cancel.Token },
                file =>
                {
                    Interlocked.Increment(ref files);
                    var ext = file.Extension;
                    try
                    {
                        if (options.Images && AiImageDetector.Extensions.Contains(ext))
                        {
                            Interlocked.Increment(ref imagesSeen);
                            if (AiImageDetector.Inspect(file) is { } image && image.Confidence >= options.MinConfidence)
                            {
                                images.Add(image);
                                Found(options, $"AI image  [{image.Confidence.ToString().ToLowerInvariant()}] {image.Generator ?? "?"}  {image.Path}",
                                    "image", image.Path, image.Generator ?? image.Kind, image.Confidence.ToString().ToLowerInvariant());
                            }
                        }
                        else if (options.Office && OfficeInspector.Extensions.Contains(ext) && !file.Name.StartsWith("~$", StringComparison.Ordinal))
                        {
                            if (file.Length > maxOffice)
                            {
                                Interlocked.Increment(ref tooLarge);
                                return;
                            }
                            Interlocked.Increment(ref officeSeen);
                            if (office.Inspect(file) is { } doc)
                            {
                                officeFiles.Add(doc);
                                var kinds = string.Join(", ", doc.Findings.Select(f => f.Kind).Distinct());
                                Found(options, $"Office    [{doc.Severity.ToString().ToLowerInvariant()}] {kinds}  {doc.Path}",
                                    "office", doc.Path, kinds, doc.Severity.ToString().ToLowerInvariant());
                            }
                        }
                    }
                    catch (Exception ex) when (ex is not OperationCanceledException)
                    {
                        if (Interlocked.Increment(ref errorCount) <= 500)
                            errors.Enqueue(new ScanError(file.FullName, $"{ex.GetType().Name}: {ex.Message}"));
                    }
                });
        }
        catch (OperationCanceledException)
        {
            // Ctrl+C: the report holds what was found until then.
        }
        progress?.Dispose();
        if (options.Progress)
            Tick();
        else if (!options.Quiet && !Console.IsErrorRedirected)
            Console.Error.Write("\r\u001b[2K");

        var (aiImages, offices) = Correlate(options, images.ToList(), officeFiles.ToList(), browsers);

        stats.Files = files;
        stats.ImagesInspected = imagesSeen;
        stats.OfficeFilesInspected = officeSeen;
        stats.SkippedTooLarge = tooLarge;
        stats.Errors = errorCount;
        stats.AiImages = aiImages.Count;
        stats.OfficeFilesWithCode = offices.Count;
        stats.BrowserProfiles = browsers?.Profiles.Count(p => p.Readable) ?? 0;
        stats.AiServices = browsers?.AiServices.Count ?? 0;

        var report = new ScanReport
        {
            Machine = Environment.MachineName,
            User = Environment.UserName,
            Os = RuntimeInformation.OSDescription,
            StartedAt = started,
            FinishedAt = DateTime.Now,
            DurationSeconds = Math.Round(clock.Elapsed.TotalSeconds, 1),
            Interrupted = cancel.IsCancellationRequested,
            Roots = roots,
            Options = options.ForReport(),
            Stats = stats,
            AiImages = aiImages.OrderByDescending(i => i.Confidence).ThenBy(i => i.Path, StringComparer.OrdinalIgnoreCase).ToList(),
            OfficeFiles = offices.OrderByDescending(o => o.Severity).ThenBy(o => o.Path, StringComparer.OrdinalIgnoreCase).ToList(),
            Browsers = browsers,
            Errors = errors.ToList(),
        };

        var json = JsonSerializer.Serialize(report, ScanReport.Json);
        if (options.Out == "-")
        {
            Console.Out.WriteLine(json);
        }
        else
        {
            var path = Path.GetFullPath(options.Out ?? $"immune-system-{started:yyyyMMdd-HHmmss}.json");
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, json);
            Log(options, $"Report: {path}");
            if (options.Progress)
                Event(new { @event = "report", path });
        }

        Log(options, $"{(report.Interrupted ? "Interrupted after" : "Done in")} {clock.Elapsed:hh\\:mm\\:ss}: {stats.Directories:N0} folders, {files:N0} files, " +
            $"{imagesSeen:N0} images → {aiImages.Count} by AI, {officeSeen:N0} Office files → {offices.Count} with code" +
            (browsers is null ? "" : $", {browsers.Profiles.Count(p => p.Readable)} browser profiles → {browsers.AiServices.Count} AI services") +
            (errorCount > 0 ? $", {errorCount} unreadable" : ""));
        return aiImages.Count == 0 && offices.Count == 0 ? 0 : 1;
    }

    /// <summary>
    /// Ties the findings to the downloads: where each file comes from (browser history, else what the system wrote on
    /// the file), what the scan found in each download, and the images downloaded from an AI service that said nothing
    /// in their metadata (then a medium clue).
    /// </summary>
    private static (List<AiImage> Images, List<OfficeFile> Office) Correlate(Options options, List<AiImage> images, List<OfficeFile> offices, BrowserReport? browsers)
    {
        var comparer = OperatingSystem.IsLinux() ? StringComparer.Ordinal : StringComparer.OrdinalIgnoreCase;
        var downloads = new Dictionary<string, BrowserDownload>(comparer);
        foreach (var d in browsers?.Downloads ?? [])
            downloads.TryAdd(d.File, d);
        string? Origin(string path) => downloads.TryGetValue(path, out var d) ? d.Source ?? d.Referrer : FileOrigin.Of(path);

        var known = new HashSet<string>(images.Select(i => i.Path), comparer);
        for (var i = 0; i < images.Count; i++)
        {
            var image = images[i];
            var origin = i < 2000 ? Origin(image.Path) : null;
            var service = AiServices.Of(origin);
            if (service is not null && image.Confidence < Confidence.High)
                image = image with
                {
                    Evidence = [.. image.Evidence, new Evidence("download", $"Downloaded from {service.Name}", Confidence.Medium)],
                    Confidence = image.Evidence.Any(e => e.Confidence == Confidence.Medium) ? Confidence.High : Confidence.Medium,
                    Generator = image.Generator ?? service.Name,
                };
            images[i] = image with { Origin = origin };
        }
        for (var i = 0; i < offices.Count; i++)
            offices[i] = offices[i] with { Origin = i < 2000 ? Origin(offices[i].Path) : null };

        if (options.Images)
            foreach (var d in browsers?.Downloads ?? [])
            {
                if (d.Kind != "image" || d.Service is null || !d.Exists || known.Contains(d.File) || Confidence.Medium < options.MinConfidence)
                    continue;
                known.Add(d.File);
                var file = new FileInfo(d.File);
                images.Add(new AiImage
                {
                    Path = file.FullName,
                    Size = file.Length,
                    Modified = file.LastWriteTime,
                    Format = file.Extension.TrimStart('.').ToLowerInvariant(),
                    Kind = "ai-generated",
                    Confidence = Confidence.Medium,
                    Generator = d.Service,
                    Origin = d.Source ?? d.Referrer,
                    Evidence = [new Evidence("download", $"Downloaded from {d.Service} with {d.Browser} (no AI mark in its metadata)", Confidence.Medium)],
                });
                Found(options, $"AI image  [medium] {d.Service}  {file.FullName}", "image", file.FullName, d.Service, "medium");
            }

        var withCode = new HashSet<string>(offices.Select(o => o.Path), comparer);
        foreach (var d in browsers?.Downloads ?? [])
            d.Finding = known.Contains(d.File) ? "ai-image" : withCode.Contains(d.File) ? "office-code" : null;
        return (images, offices);
    }

    private static readonly object ConsoleLock = new();

    private static void Log(Options options, string line)
    {
        if (options.Progress)
        {
            Event(new { @event = "log", text = line });
            return;
        }
        if (options.Quiet)
            return;
        lock (ConsoleLock)
            Console.Error.WriteLine(line);
    }

    private static void Found(Options options, string line, string type, string path, string label, string level)
    {
        if (options.Progress)
        {
            Event(new { @event = "found", type, path, label, level });
            return;
        }
        if (options.Quiet)
            return;
        lock (ConsoleLock)
        {
            if (!Console.IsErrorRedirected)
                Console.Error.Write("\r\u001b[2K");
            Console.Error.WriteLine(line);
        }
    }

    private static readonly JsonSerializerOptions EventJson = new() { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };

    /// <summary>One JSON line on the error output (<c>--progress</c>).</summary>
    private static void Event(object e)
    {
        var line = JsonSerializer.Serialize(e, EventJson);
        lock (ConsoleLock)
        {
            Console.Error.WriteLine(line);
            Console.Error.Flush();
        }
    }

    private static void Progress(Options options, long files, long directories, long images, long office, int aiImages, int officeWithCode, string folder, double seconds)
    {
        if (options.Progress)
        {
            Event(new { @event = "progress", files, directories, images, office, aiImages, officeWithCode, folder, seconds = Math.Round(seconds, 1) });
            return;
        }
        lock (ConsoleLock)
        {
            var width = Console.IsErrorRedirected ? 120 : Math.Max(40, Console.WindowWidth - 1);
            var line = $"{files:N0} files · {aiImages} AI images · {officeWithCode} Office files with code · {folder}";
            if (line.Length > width)
                line = line[..(width - 1)] + "…";
            Console.Error.Write("\r\u001b[2K" + line);
        }
    }
}
